import java.util.*;

class Excel {
  private final int height;
  private final int width;
  private final Cell[][] cells;

  public Excel(int height, char width) {
    this.height = height;
    this.width = width - 'A' + 1;
    cells = new Cell[height][this.width];
    for (int r = 0; r < height; r++) {
      for (int c = 0; c < this.width; c++) cells[r][c] = new Cell();
    }
  }

  public void set(int row, char column, int value) {
    Cell cell = cells[row - 1][column - 'A'];
    cell.value = value;
    cell.formula = null;
  }

  public int get(int row, char column) {
    return evaluate(row - 1, column - 'A', new boolean[height][width]);
  }

  public void sum(int row, char column, String[] numbers) {
    Cell cell = cells[row - 1][column - 'A'];
    cell.formula = new HashMap<>();
    for (String token : numbers) {
      String[] ends = token.split(":");
      String start = ends[0];
      String end = ends.length == 1 ? start : ends[1];
      int r1 = Integer.parseInt(start.substring(1)) - 1;
      int r2 = Integer.parseInt(end.substring(1)) - 1;
      int c1 = start.charAt(0) - 'A';
      int c2 = end.charAt(0) - 'A';
      for (int r = r1; r <= r2; r++) {
        for (int c = c1; c <= c2; c++) {
          String key = r + ":" + c;
          cell.formula.put(key, cell.formula.getOrDefault(key, 0) + 1);
        }
      }
    }
  }

  private int evaluate(int row, int column, boolean[][] visiting) {
    Cell cell = cells[row][column];
    if (cell.formula == null) return cell.value;
    if (visiting[row][column]) throw new IllegalStateException("Circular formula reference");
    visiting[row][column] = true;
    int result = 0;
    for (Map.Entry<String, Integer> entry : cell.formula.entrySet()) {
      String[] position = entry.getKey().split(":");
      result +=
          entry.getValue()
              * evaluate(Integer.parseInt(position[0]), Integer.parseInt(position[1]), visiting);
    }
    visiting[row][column] = false;
    return result;
  }

  private static class Cell {
    int value;
    Map<String, Integer> formula;
  }
}
